query.base:
TS metrics-gcp.cloudsql_postgresql.otel-*
| WHERE gcp.resource_type == "cloudsql_database"
// For fleets with HA (regional) instances. available_for_failover (GAUGE, >0 = standby
// ready) is reported only for HA instances, so zonal instances never alert. If no HA
// instance has ever reported, the field is unmapped and the query fails with
// "Unknown column": the rule does not apply to that fleet.
// Resolve per minute first (fragmentation-safe).
| STATS failover_ready = MAX(MAX_OVER_TIME(`cloudsql.googleapis.com/database/available_for_failover`)),
        pg = SUM(COUNT_OVER_TIME(`cloudsql.googleapis.com/database/postgresql/num_backends`))
    BY `@timestamp` = TBUCKET(1 minute), database_id
// PostgreSQL engine marker: excludes MySQL / SQL Server HA instances
| INLINE STATS pg_total = SUM(pg) BY database_id
| WHERE pg_total > 0 AND failover_ready IS NOT NULL
// Latest readiness sample per instance
| STATS failover_ready = LAST(failover_ready, `@timestamp`),
        ready_minutes = COUNT(*)
    BY database_id

breach.segment:
// Breach: the standby cannot take over (HA protection lost). After an automatic failover
// this can also show while the standby is rebuilt.
WHERE failover_ready == 0
| KEEP database_id, failover_ready, ready_minutes
| SORT database_id
| LIMIT 100
